{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name AS dep, count(*) AS n, round(avg(\"value\"),2) AS avg_available FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='profile' GROUP BY 1", "claim": "Profile deployment reports available=0 across the abnormal window; normal average was 1.0."},
        {"kind": "metric", "sql": "SELECT 'abn' p, count(*) n FROM abnormal_metrics_sum WHERE metric='k8s.pod.uptime' AND attr_k8s_deployment_name='profile' UNION ALL SELECT 'norm', count(*) FROM normal_metrics_sum WHERE metric='k8s.pod.uptime' AND attr_k8s_deployment_name='profile'", "claim": "Profile pod uptime samples vanish in the abnormal window (0 rows versus 31 normal), so the pod stopped and stayed gone."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY 1,2", "claim": "All 677 frontend calls to profile.GetProfiles return Error in about 0.01 ms, with no successful calls."},
        {"kind": "log", "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE message='Get profiles failed' GROUP BY 1,2", "claim": "Frontend logs 'Get profiles failed' 862 times; profile service itself emits no logs in the abnormal window."}
      ]
    },
    {
      "service": "search",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2", "claim": "Search's calls to rate.GetRates all fail with Error in about 0.01 ms, versus about 1.2 ms normal, so no connection is made."},
        {"kind": "trace", "sql": "SELECT count(*) AS rate_spans_abnormal FROM abnormal_traces WHERE service_name='rate'", "claim": "The rate service emits zero spans in the abnormal window, though it had 1710 in normal."},
        {"kind": "log", "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY 1,2", "claim": "Search logs 'Failed to get rates from rate service' 1442 times in the abnormal window."},
        {"kind": "metric", "sql": "SELECT attr_k8s_deployment_name AS dep, metric, round(avg(\"value\"),2) avg_v FROM abnormal_metrics_sum WHERE attr_k8s_deployment_name='search' AND metric='k8s.pod.network.errors' GROUP BY 1,2", "claim": "Search pod shows zero network errors, and rate's pod uptime continues without restart, so this is a name-resolution failure rather than a pod restart."}
      ]
    }
  ],
  "propagation": [
    {"from": "profile", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('profile.Profile/GetProfiles','HTTP /recommendations') GROUP BY 1,2,3", "claim": "Frontend GetProfiles calls fail in 0.01 ms, and every /recommendations request then returns HTTP 500."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2", "claim": "Search failures propagate to frontend: all 1118 /hotels requests return HTTP 500, versus 921 HTTP 200 in normal."}]}
  ]
}
